        /// <summary>
        /// Prefijos de c?digo de cara en el mismo orden que el enum SkinColour
        /// (SKIN_COLOUR_1 = W, SKIN_COLOUR_2 = Y, SKIN_COLOUR_3 = R, SKIN_COLOUR_4 = K).
        /// </summary>
        public static readonly string[] SkinColourPrefixes = { "W", "Y", "R", "K" };

        /// <summary>
        /// Devuelve el mayor FaceId disponible para el prefijo indicado (ej. "K" -> 24),
        /// seg?n los c?digos cargados en FacePlayers. Si no hay coincidencias, devuelve 0.
        /// </summary>
        public static int GetMaxFaceId(string prefix)
        {
            int max = 0;
            foreach (FacePlayer player in FacePlayers)
            {
                if (player.FaceCode != null &&
                    player.FaceCode.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) &&
                    int.TryParse(player.FaceCode.Substring(prefix.Length), out int faceId) &&
                    faceId > max)
                {
                    max = faceId;
                }
            }

            return max;
        }

        /// <summary>
        /// Devuelve el mayor FaceId disponible para el SkinColour indicado.
        /// </summary>
        public static int GetMaxFaceId(SkinColour skinColour)
        {
            int prefixIndex = (int)skinColour;
            if (prefixIndex < 0 || prefixIndex >= SkinColourPrefixes.Length)
            {
                return 0;
            }

            return GetMaxFaceId(SkinColourPrefixes[prefixIndex]);
        }
    }
